mapper.select:
SELECT id, order_id as orderId, order_no as orderNo, merchant_id as merchantId,
       operator_id as operatorId, operator_name as operatorName,
       operation_type as operationType, operation_desc as operationDesc,
       before_status as beforeStatus, after_status as afterStatus,
       remark, extend_data as extendData, create_time as createTime
FROM order_operation_log
WHERE merchant_id = #{merchantId}

    AND operation_type = #{operationType}


    AND create_time >= #{startDate}


    AND create_time <= #{endDate}

ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM order_operation_log
WHERE merchant_id = #{merchantId}

    AND operation_type = #{operationType}


    AND create_time >= #{startDate}


    AND create_time <= #{endDate}
